const e=document.getElementById("mobile-menu-button"),t=document.getElementById("mobile-menu");e?.addEventListener("click",()=>{t?.classList.contains("hidden")===!1?(t?.classList.add("hidden"),e.setAttribute("aria-expanded","false"),e.setAttribute("aria-label","Abrir menú de navegación")):(t?.classList.remove("hidden"),e.setAttribute("aria-expanded","true"),e.setAttribute("aria-label","Cerrar menú de navegación"))});
